import sys

def main():
    input = sys.stdin.read
    data = input().split()

    D = int(data[0])
    G = int(data[1])

    p = []
    c = []

    index = 2
    for _ in range(D):
        p.append(int(data[index]))
        c.append(int(data[index + 1]))
        index += 2

    dp = [float('inf')] * (G + 1)
    dp[0] = 0

    for i in range(D):
        for j in range(G // 100 + 1):
            if j * 100 <= G:
                dp[j * 100] = min(dp[j * 100], j * p[i])

    for i in range(D):
        for j in range(G // 100, -1, -1):
            if j * 100 <= G:
                dp[j * 100 + c[i]] = min(dp[j * 100 + c[i]], dp[j * 100] + p[i])

    result = float('inf')
    for i in range(G // 100 + 1):
        if dp[i * 100] <= G:
            result = min(result, i)

    print(result)

if __name__ == "__main__":
    main()
